"""Reconcile two CSV exports and print the differing rows."""

import csv
import sys


def rows(path):
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def main(left, right):
    seen = {tuple(sorted(row.items())) for row in rows(left)}
    for row in rows(right):
        if tuple(sorted(row.items())) not in seen:
            print(row)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
